fun text r newText =>
  have start := text.lspPosToUtf8Pos r.start;
  have «end» := text.lspPosToUtf8Pos r.end;
  have pre := String.Pos.Raw.extract text.source 0 start;
  have post := String.Pos.Raw.extract text.source «end» text.source.rawEndPos;
  (pre ++ newText.crlfToLf ++ post).toFileMap

