fun stx =>
  (stx.find? fun x =>
      have __discr := x;
      if __discr.isOfKind `Lean.Parser.Term.sorry = true then
        have __discr := __discr.getArg 0;
        true
      else
        have __discr := x;
        if __discr.isOfKind `Lean.Parser.Tactic.tacticSorry = true then
          have __discr := __discr.getArg 0;
          true
        else
          have __discr := x;
          if __discr.isOfKind `Lean.Parser.Tactic.tacticAdmit = true then
            have __discr := __discr.getArg 0;
            true
          else
            have __discr := x;
            false).isSome

